// react
import {useState, useCallback, useEffect, useRef, useMemo, Component} from 'react'

// fontawesome
import {faArrowRotateLeft,faCompress,faExpand,faDownload,faSquareMinus,faSquarePlus,faTable,faCode,faStop,faArrowsRotate} from '@fortawesome/free-solid-svg-icons'

// custom
import './App.css'

// util
import * as util from './Util.js'
Object.assign(global, util)

export default function Win({id=null, title, addTools, content, minimizable=true, highlight=null, evaluating=false, winref=null, winbodystyle={}}) {
  if (id == null) id = title

  // util
  const key = (attr) => `Win_${title}_${attr}`
  
  // state
  const minimized = useStore(key('minimized'), false)
  const [hover, setHover] = useState(false)
  
  // tool callbacks
  const onMinimize = useCallback(() => minimized.set(!minimized.val), 
    [minimized.val])

  // const activeTools = tools.filter(t => t.active)
  const tools = {
    minimize:   toolButton({
                  id: 'minimize',
                  title: minimized.val ? 'Show' : 'Hide',
                  icon:  minimized.val ? faSquarePlus : faSquareMinus,
                  click: onMinimize,
                }),
    evaling:    toolButton({
                  id: 'evaling',
                  title: 'Loading...',
                  icon:  faArrowsRotate,
                  iconClass: 'spin',
                }),
  }    
  
  const winref1 = winref == null ? useRef(null)
                                 : winref
  const overlayStyle = winref1.current != null ? {
    width: winref1.current.clientWidth,
    height: winref1.current.clientHeight,
    marginTop: -winref1.current.clientHeight,
 } : {}

  return (
    <div
      ref={winref1}
      className={`window ${highlight?.val ? 'highlight' : ''}`}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
    >
      <div className={`titlebar ${minimized ? 'minimized' : ''} ${highlight?.val ? 'highlight' : ''}`}>
        {minimizable &&
          tools.minimize}
        <span className='title' style={{paddingRight: '4px'}}>{title}</span>
        {evaluating ?
          tools.evaling
          : (hover && !minimized.val &&
            <div className='toolrow'>
              {addTools}
            </div>)
        }
      </div>
      <div className='windowBody' style={{overflow: 'hidden', ...winbodystyle}}>
        {!minimized.val &&
          content}
      </div>
      {highlight?.val && 
        <div className='overlay' style={overlayStyle} />}
    </div>
  )
}
