export default "using System.Collections.Generic;\r\nusing UnityEngine;\r\nusing UnityEngine.UI;\r\nusing TMPro;\r\n\r\npublic class Skill : MonoBehaviour {\r\n    public string name;\r\n    public int cost;\r\n    public bool purchased;\r\n    public bool unlocked;\r\n    public List<Skill> next;\r\n\r\n    ///////\r\n    // UTIL\r\n    ///////\r\n    void UpdateUI() {\r\n        transform.GetChild(0).gameObject.GetComponent<TMP_Text>().text = name;\r\n        transform.GetChild(1).gameObject.GetComponent<TMP_Text>().text = $\" ${cost}\";\r\n        transform.GetChild(1).gameObject.SetActive(!purchased);\r\n        GetComponent<Image>().color = purchased ? Color.green : Color.white;   \r\n        GetComponent<Button>().interactable = unlocked;\r\n        GetComponent<Button>().enabled = !purchased;\r\n    }\r\n\r\n    /////////\r\n    // PUBLIC\r\n    /////////\r\n    public void Enable(bool enabled) {\r\n        unlocked = enabled;\r\n        UpdateUI();\r\n    }\r\n    public void Purchase() {\r\n        purchased = true;\r\n        ES3.SaveBool($\"{name}_purchased\", true);\r\n        UpdateUI();\r\n    }\r\n    public void Reset() {\r\n        purchased = false;\r\n        unlocked = false;\r\n        ES3.SaveBool($\"{name}_purchased\", false);\r\n    }\r\n    \r\n    ///////////////\r\n    // UNITY EVENTS\r\n    ///////////////\r\n    void OnClick() {\r\n        SkillTree st = transform.parent.gameObject.GetComponent<SkillTree>();\r\n        st.ShowConfirmation(this);\r\n    }\r\n    void Awake() {\r\n        GetComponent<Button>().onClick.AddListener(OnClick);\r\n        purchased = ES3.LoadBool($\"{name}_purchased\", false);\r\n        UpdateUI();\r\n    }\r\n}\r\n";